// Generate the two engine data modules that keep the Lab and the specification pages on ONE editorial decision set.
// Inputs (Work's reviewed reference package, 47501c2): _build/reference-editorial.json, reference-reviewed.json,
// reference-oem.json. Outputs (committed, regenerated by _build/build.py):
//   engine/data/publication.mjs       archive configurations held or withheld from publication (and from the Lab)
//   engine/data/archive-corrections.mjs  manufacturer-sourced model inputs that take precedence over archive values
// No engine import here, so engine modules can depend on the outputs without a cycle.
import { readFileSync, writeFileSync } from 'node:fs';

const here = new URL('./', import.meta.url);
const json = p => JSON.parse(readFileSync(new URL(p, here), 'utf8'));
const editorial = json('../reference-editorial.json');
const oem = json('../reference-oem.json');
const reviewed = json('../reference-reviewed.json');

// The ESS predecessor car is withheld pending owner approval (reference_pages.py EDITORIAL_HOLD).
const withheld = { 'sx-1977-pontiac-supercar-x-firebird-formula': 'ESS development predecessor. Owner approval required for project details.' };
const holds = Object.fromEntries(Object.entries(editorial.archive_holds).map(([id, h]) => [id, `${h.class}: ${h.reason}`]));

// Only manufacturer-class facts in US customary SAE units replace archive model inputs. Road-test publication values
// (as-tested weight, magazine ratings) and metric/DIN ratings stay as displayed alternates: different definitions,
// not corrections. Every replaced value keeps the archive value for display and audit.
// Peak-rpm points are not replaced: the archive's redline/shift rpm pairs with its own peak rpm, and mixing sources
// can put the power peak at or above the shift rpm (2005 Ford GT: brochure 6,500 rpm peak vs archive 6,500 redline).
const KEYS = [[/^rated power$/i, 'hp', 'hp'], [/^rated torque$/i, 'torque', 'lb-ft'], [/^wheelbase$/i, 'wheelbase', 'in'], [/^front track$/i, 'frontTrack', 'in'],
  [/^rear track$/i, 'rearTrack', 'in'], [/^final drive ratio$/i, 'finalDrive', 'ratio'], [/^curb weight$/i, 'weight', 'lb']];
const corrections = {};
for (const [id, review, isOem] of [...Object.entries(oem).map(([k, v]) => [k, v, true]), ...Object.entries(reviewed).map(([k, v]) => [k, v, false])]) {
  const evidence = review.evidence ?? (isOem ? 'manufacturer' : 'published');
  if (evidence !== 'manufacturer') continue;
  for (const facts of Object.values(review.fields)) for (const [label, value, unit = '', note = ''] of facts) {
    const hit = KEYS.find(([re, , u]) => re.test(label) && (unit || '') === (u === 'ratio' ? (unit || 'ratio') : u));
    if (!hit || typeof value !== 'number') continue;
    (corrections[id] ??= {})[hit[1]] = [value, 'manufacturer', review.url, `${review.publisher}. ${note || review.scope}`.trim()];
  }
}

const banner = '// GENERATED by _build/knowledge/engine-data.mjs from Work\'s reviewed reference package. Do not edit by hand.\n';
writeFileSync(new URL('../../engine/data/publication.mjs', here), banner +
  `// Archive configurations not published and not offered in the Lab until their identity or approval is resolved.\n` +
  `export const archiveWithheld = ${JSON.stringify(withheld, null, 1)};\nexport const archiveHolds = ${JSON.stringify(holds, null, 1)};\n` +
  `export const notPublishable = id => Object.hasOwn(archiveWithheld, id) || Object.hasOwn(archiveHolds, id);\n`);
writeFileSync(new URL('../../engine/data/archive-corrections.mjs', here), banner +
  `// Manufacturer-sourced values that replace the Supercar X value for the same quantity: [value, evidence, source url, note].\n` +
  `export const archiveCorrections = ${JSON.stringify(corrections, null, 1)};\n`);
console.log(JSON.stringify({ holds: Object.keys(holds).length, withheld: Object.keys(withheld).length,
  corrected: Object.fromEntries(Object.entries(corrections).map(([k, v]) => [k, Object.keys(v)])) }));
